```{.r .cell-code}
site_metadata <- site_metadata |>
  mutate(dom_hali = as.integer(dominant_family == "Halictidae"),
         cent_temp = annual_mean_temp - mean(annual_mean_temp),
         cent_lat = latitude - mean(latitude))
```
:::



::: {.cell}

```{.r .cell-code}
glm_hali <- glm(dom_hali ~ cent_lat * cent_temp, data = site_metadata,
                family = binomial)
print (summary(glm_hali))
```

